'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['createAudioSession', 'reduceAudioSession']);
const { createAudioSession, reduceAudioSession } = api;

const initial = createAudioSession();
assert.deepEqual(initial, { route: '/', trackId: null, playing: false, position: 0, caption: '' });

let state = reduceAudioSession(initial, { type: 'LOAD', trackId: 'track-1' });
assert.deepEqual(state, { route: '/', trackId: 'track-1', playing: false, position: 0, caption: '' });
assert.notStrictEqual(state, initial);
assert.deepEqual(initial, { route: '/', trackId: null, playing: false, position: 0, caption: '' });

let next = reduceAudioSession(state, { type: 'PLAY' });
assert.equal(next.playing, true);
assert.notStrictEqual(next, state);
const noTrackPlay = reduceAudioSession(initial, { type: 'PLAY' });
assert.equal(noTrackPlay.playing, false);
assert.notStrictEqual(noTrackPlay, initial);

next = reduceAudioSession(next, { type: 'SEEK', position: 12.5 });
next = reduceAudioSession(next, { type: 'CAPTION', caption: 'hello' });
assert.equal(next.position, 12.5);
assert.equal(next.caption, 'hello');
const beforeRoute = next;
const routeAction = { type: 'ROUTE_CHANGED', route: '/library' };
const routed = reduceAudioSession(beforeRoute, routeAction);
assert.deepEqual(routed, { route: '/library', trackId: 'track-1', playing: true, position: 12.5, caption: 'hello' });
assert.deepEqual(beforeRoute, { route: '/', trackId: 'track-1', playing: true, position: 12.5, caption: 'hello' });
assert.deepEqual(routeAction, { type: 'ROUTE_CHANGED', route: '/library' });

const paused = reduceAudioSession(routed, { type: 'PAUSE' });
assert.equal(paused.playing, false);
assert.notStrictEqual(paused, routed);
const zeroSeek = reduceAudioSession(paused, { type: 'SEEK', position: 0 });
assert.equal(zeroSeek.position, 0);
const loadedAgain = reduceAudioSession(routed, { type: 'LOAD', trackId: '' });
assert.deepEqual(loadedAgain, { route: '/library', trackId: '', playing: false, position: 0, caption: '' });

const malformedStates = [
  null, {}, [],
  { route: 1, trackId: null, playing: false, position: 0, caption: '' },
  { route: '/', trackId: 1, playing: false, position: 0, caption: '' },
  { route: '/', trackId: null, playing: 0, position: 0, caption: '' },
  { route: '/', trackId: null, playing: false, position: -1, caption: '' },
  { route: '/', trackId: null, playing: false, position: Infinity, caption: '' },
  { route: '/', trackId: null, playing: false, position: 0, caption: null }
];
for (const bad of malformedStates) assert.throws(() => reduceAudioSession(bad, { type: 'PAUSE' }), TypeError);

const malformedActions = [
  null, undefined, {}, [], { type: 1 }, { type: 'UNKNOWN' },
  { type: 'LOAD' }, { type: 'LOAD', trackId: 1 },
  { type: 'SEEK' }, { type: 'SEEK', position: -1 }, { type: 'SEEK', position: NaN }, { type: 'SEEK', position: Infinity }, { type: 'SEEK', position: '1' },
  { type: 'CAPTION' }, { type: 'CAPTION', caption: null },
  { type: 'ROUTE_CHANGED' }, { type: 'ROUTE_CHANGED', route: 1 }
];
for (const bad of malformedActions) assert.throws(() => reduceAudioSession(initial, bad), TypeError);

